from pathlib import Path
import zipfile,subprocess
for n in ['MacElray\'s Managerie.odt','Pony.odt','Poula Builds A Pony.rtf']:
 p=Path('/mnt/data/storyo_archaeology')/n
 print('\n',n,p.read_bytes()[:32])
 if zipfile.is_zipfile(p):
  with zipfile.ZipFile(p) as z:
   print(z.namelist()[:10]);
   for x in ['content.xml','mimetype']:
    if x in z.namelist(): print(x,z.read(x)[:200])
 else:
  print(subprocess.run(['file',str(p)],capture_output=True,text=True).stdout)
PY

bash -lc file /mnt/data/storyo_archaeology/* | head -25; python - <<'PY'
from pathlib import Path
import zipfile
for p in Path('/mnt/data/storyo_archaeology').glob('*.odt'):
 print('\n',p.name)
 try:
  with zipfile.ZipFile(p) as z:
   for i in z.infolist():
    if i.filename in ('content.xml','mimetype','META-INF/manifest.xml'):
