"""STORYO v0.8 facet-level graph engine. Standard library only."""
from __future__ import annotations
import csv
from collections import defaultdict, deque
from pathlib import Path

ALLOWED = {"epistemic", "motivation", "causal", "interpretive_causal", "character_belief", "epistemic_revelation", "explicit_motivation", "institutional"}
NECESSITY = {"necessary": 1.0, "enabling": 0.8, "contributing": 0.5, "resonant": 0.0}

def read_rows(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))

def load_graph(directory):
    directory = Path(directory)
    facets = read_rows(directory / "event_facets.csv")
    dependencies = read_rows(directory / "facet_dependencies.csv")
    ids = {x["facet_id"] for x in facets}
    for edge in dependencies:
        if edge["source_facet"] not in ids or edge["target_facet"] not in ids:
            raise ValueError(f"Dangling dependency: {edge['dependency_id']}")
    return facets, dependencies

def effective_weight(edge):
    confidence = float(edge.get("confidence_factor", edge.get("weight", 0.5)))
    necessity = NECESSITY.get(edge["necessity"], 0.0)
    return confidence * necessity

def compute_sensitivity(facets, dependencies):
    adjacency = defaultdict(list)
    for edge in dependencies:
        if edge["dependency_type"] in ALLOWED:
            adjacency[edge["source_facet"]].append(edge)
    output = []
    for facet in facets:
        start = facet["facet_id"]
        best = {}
        queue = deque([(start, 1.0, 0)])
        while queue:
            node, score, depth = queue.popleft()
            if depth >= 12:
                continue
            for edge in adjacency.get(node, []):
                target = edge["target_facet"]
                candidate = score * effective_weight(edge)
                if target != start and candidate > best.get(target, 0.0) + 1e-12:
                    best[target] = candidate
                    queue.append((target, candidate, depth + 1))
        ranked = sorted(best.items(), key=lambda x: (-x[1], x[0]))
        output.append({"facet_id": start, "parent_event_id": facet["parent_event_id"],
                       "reachable_downstream_facets": len(ranked),
                       "weighted_downstream_influence": round(sum(v for _, v in ranked), 4),
                       "max_single_path_influence": round(max(best.values(), default=0.0), 4),
                       "top_downstream": ";".join(f"{k}:{v:.3f}" for k, v in ranked[:5])})
    return sorted(output, key=lambda x: (-x["weighted_downstream_influence"], x["facet_id"])))

def propagate(changed_facets, dependencies):
    """Return graph-reachable candidates. Reachability is not inevitability."""
    adjacency = defaultdict(list)
    for edge in dependencies:
        if edge["dependency_type"] in ALLOWED:
            adjacency[edge["source_facet"]].append(edge)
    direct = list(dict.fromkeys(changed_facets))
    found = {}
    queue = deque((x, 0) for x in direct)
    while queue:
        node, depth = queue.popleft()
        if depth >= 12:
            continue
        for edge in adjacency.get(node, []):
            target = edge["target_facet"]
            if target not in direct and target not in found:
                found[target] = {"via": node, "dependency_id": edge["dependency_id"],
                                 "dependency_type": edge["dependency_type"],
                                 "necessity": edge["necessity"],
                                 "effective_weight": round(effective_weight(edge), 4),
                                 "status": "DEPENDENCY_CANDIDATE_NOT_GUARANTEED"}
                queue.append((target, depth + 1))
    return {"directly_changed": direct, "downstream_candidates": found,
            "not_modeled_as_causal": "Presentation order and thematic resonance are excluded."}

if __name__ == "__main__":
    import json, sys
    here = Path(__file__).resolve().parent
    facets, deps = load_graph(here)
    print(json.dumps({"sensitivity": compute_sensitivity(facets, deps),
                      "CF01_propagation": propagate(["EV18b"], deps)}, indent=2))
